/**
 * Academy study bank: original flashcards and practice questions (no copied exam questions, no AI generation at
 * runtime). Regulatory items cite a verified section and carry `p`, a phrase that must appear word for word in that
 * section's official text; scripts/academy/kb/gen-study-seed.ts refuses to build if it doesn't. Concept items
 * (definitions, codebook navigation, business basics) state general knowledge and carry no section.
 *
 * Fields: k key · d deck · q prompt · a answer · o options (makes it a multiple-choice question; must include a)
 * · x explanation · s section key ("cfr:1926.501(b)" / "mn:1309.0311 subp. 2") · p proof phrase · t trades · l level.
 */
export type Level = "easy" | "medium" | "hard";
export interface StudyItem { k: string; d: string; q: string; a: string; o?: string[]; x?: string; s?: string; p?: string; t?: string[]; l?: Level }

export interface Deck { slug: string; title: string; about: string; state?: string; trades: string[] }
